import {INSTRUMENTS,noteName,instrumentSettings} from './beat-instruments.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createPianoEditor(root,{patterns,uid,changed,beforeChange=()=>{},addToPlaylist,hit,padHit,clock,musicalClock,rename,notify}){
 let id=null,snap=.25,length=1,velocity=.8,octave=3,zoom=48,rowHeight=44,mode='draw',multi=false,selected=new Set(),clipboard=[],undo=[],redo=[],drag=null,keys=new Map(),drumHolds=new Map(),armed=false,recordAt=null,rendering=false;
 const q=s=>root.querySelector(s),all=s=>root.querySelectorAll(s),current=()=>patterns().find(p=>p.id===id&&p.kind==='notes'),quantize=n=>Math.round(n/snap)*snap;
 function ensure(){if(!current()){id=patterns().find(p=>p.kind==='notes')?.id;if(!id)create();}return current();}
 function create(){const p={id:uid(),name:'Melody '+(patterns().filter(p=>p.kind==='notes').length+1),kind:'notes',beats:16,instrument:'piano',voice:{},notes:[]};patterns().push(p);id=p.id;selected.clear();undo=[];redo=[];changed();return p;}
 function remember(){beforeChange();undo.push(structuredClone(current()));if(undo.length>40)undo.shift();redo=[];}
 function act(fn){if(rendering)return;try{remember();fn(current());changed();render();}catch(e){const old=undo.pop();if(old)Object.assign(current(),old);notify(e.message,'error');render();}}
 function insert(p,notes){if(p.notes.length+notes.length>256||notes.some(n=>n.start<0||n.start+n.length>p.beats||n.pitch<24||n.pitch>108))throw Error('Keep notes inside this pattern (up to 256 notes).');p.notes.push(...notes);selected=new Set(notes.map(n=>n.id));}
 function render(){if(keys.size||drumHolds.size||drag)return;const p=ensure(),settings=instrumentSettings(p),old=q('.pr-scroll'),scroll=old?{x:old.scrollLeft,y:old.scrollTop}:null,focus=root.contains(document.activeElement)?document.activeElement.id:null,base=12*(octave+1),top=Math.min(108,base+23),rows=top-base+1,first=p.notes.find(n=>selected.has(n.id));
 root.style.setProperty('--row',rowHeight+'px');rendering=true;root.innerHTML=`<h2>Piano Roll · notes and instruments</h2><p>Tap the grid to add notes; drag a note to move or its right handle to resize; use Pan to scroll. Play chords on the live keys below, with drums alongside. Pattern preview uses the master Play button here; open Playlist to play your full song.</p><div class="pr-controls"><label>Pattern<select id="prPattern">${patterns().filter(p=>p.kind==='notes').map(x=>`<option value="${esc(x.id)}" ${x.id===id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button id="prNew">NEW</button><button id="prRename">RENAME / SAVE PATTERN</button><button id="prCopyPattern">DUPLICATE PATTERN</button><button id="prDeletePattern">DELETE PATTERN</button><button id="prAdd" class="btn primary">ADD TO PLAYLIST</button><label>Instrument<select id="prInstrument">${INSTRUMENTS.map(i=>`<option value="${i.id}" ${i.id===p.instrument?'selected':''}>${i.name}</option>`).join('')}</select></label><label>Pattern beats<select id="prBeats">${[4,8,16,32,64,128].map(n=>`<option ${p.beats===n?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="pr-controls"><label>Octave<select id="prOctave">${[1,2,3,4,5,6,7].map(n=>`<option ${n===octave?'selected':''}>${n}</option>`).join('')}</select></label><label>Snap<select id="prSnap">${[[4,'Whole'],[2,'Half'],[1,'Quarter'],[.5,'Eighth'],[.25,'Sixteenth'],[.125,'32nd']].map(([n,label])=>`<option value="${n}" ${n===snap?'selected':''}>${label}</option>`).join('')}</select></label><label>New note beats<input id="prLength" type="number" min=".125" max="32" step=".125" value="${length}"></label><label>Velocity<input id="prVelocity" type="range" min=".01" max="1" step=".01" value="${velocity}"></label><label>Zoom<input id="prZoom" type="range" min="24" max="100" value="${zoom}"></label><label>Note height<input id="prRowZoom" type="range" min="24" max="56" step="4" value="${rowHeight}"></label><label>Tool<select id="prTool">${['draw','select','erase','pan'].map(n=>`<option ${mode===n?'selected':''}>${n}</option>`).join('')}</select></label><label><input id="prMulti" type="checkbox" ${multi?'checked':''}>Select several</label><label>Paste at beat<input id="prPasteAt" type="number" min="0" max="128" value="0" step="${snap}"></label></div><div class="pr-scroll" tabindex="0" role="region" aria-label="Piano note grid"><div class="pr-ruler" style="width:${72+p.beats*zoom}px"><span>NOTE / BAR</span>${Array.from({length:Math.ceil(p.beats/4)},(_,i)=>`<b style="left:${72+i*4*zoom}px">${i+1}</b>`).join('')}</div><div class="pr-surface" style="width:${72+p.beats*zoom}px;height:${rows*rowHeight}px"><div class="pr-labels">${Array.from({length:rows},(_,r)=>`<span>${noteName(top-r)}</span>`).join('')}</div><div id="prGrid" style="left:72px;width:${p.beats*zoom}px;height:${rows*rowHeight}px;--beat:${zoom}px">${p.notes.filter(n=>n.pitch>=base&&n.pitch<=top).map(n=>`<div data-pr-note="${esc(n.id)}" class="pr-note ${selected.has(n.id)?'selected':''}" role="group" aria-label="${noteName(n.pitch)} at beat ${n.start}" style="left:${n.start*zoom}px;top:${(top-n.pitch)*rowHeight}px;width:${Math.max(36,n.length*zoom)}px;opacity:${.5+n.velocity*.5}"><button data-pr-select>${noteName(n.pitch)}</button><button data-pr-resize aria-label="Resize ${noteName(n.pitch)}">↔</button></div>`).join('')}<div class="pr-playhead"></div></div></div></div><div class="pr-controls"><button id="prDelete">DELETE NOTES</button><button id="prDuplicate">DUPLICATE NOTES</button><button id="prCopy">COPY</button><button id="prPaste" ${clipboard.length?'':'disabled'}>PASTE</button><button id="prQuantize">QUANTIZE</button><button id="prUndo" ${undo.length?'':'disabled'}>UNDO</button><button id="prRedo" ${redo.length?'':'disabled'}>REDO</button>${first?`<label>Pitch · MIDI<input id="prPitchEdit" type="number" min="24" max="108" value="${first.pitch}"></label><label>Start · beats<input id="prStartEdit" type="number" min="0" max="128" step="${snap}" value="${first.start}"></label><label>Length · beats<input id="prLengthEdit" type="number" min=".03125" max="32" step="${snap}" value="${first.length}"></label><label>Velocity<input id="prVelocityEdit" type="number" min=".01" max="1" step=".01" value="${first.velocity}"></label>`:''}</div><details><summary>Instrument envelope, filter and mix</summary><div class="pr-controls">${[['attack',.001,2,.001],['decay',.01,3,.01],['sustain',0,1,.01],['release',.01,3,.01],['cutoff',100,18000,100],['volume',0,1,.01],['pan',-1,1,.01]].map(([name,min,max,step])=>`<label>${name}<input data-pr-voice="${name}" type="range" min="${min}" max="${max}" step="${step}" value="${settings[name]}"></label>`).join('')}</div></details><div class="pr-controls"><button id="prRecord" aria-pressed="${armed}">${armed?'STOP NOTE CAPTURE':'CAPTURE LIVE NOTES'}</button><p>Note capture stores actual timing, up to 8 seconds per held key; Quantize afterward if wanted. Master Record Song also captures live drums and keys together. Original synthesized instrument voices, not acoustic recordings.</p></div><div class="pr-keyboard" role="group" aria-label="Live instrument keyboard">${Array.from({length:Math.min(24,109-base)},(_,i)=>{const n=base+i;return `<button data-pr-key="${n}" class="${[1,3,6,8,10].includes(n%12)?'black':'white'}" aria-label="Play ${noteName(n)}">${noteName(n)}</button>`;}).join('')}</div><h3>Drums alongside your keyboard</h3><div class="pr-pads">${Array.from({length:16},(_,i)=>`<button data-pr-pad="${i}">Pad ${i+1}</button>`).join('')}</div>`;
 q('#prPattern').onchange=e=>{if(keys.size||drumHolds.size){e.target.value=id;notify('Release keys and pads before switching patterns.');return;}id=e.target.value;selected.clear();undo=[];redo=[];beforeChange();changed();render()};q('#prNew').onclick=()=>{if(keys.size||drumHolds.size){notify('Release keys and pads first.');return;}create();render()};q('#prRename').onclick=()=>rename(p.name,name=>act(p=>p.name=name));q('#prCopyPattern').onclick=()=>{if(keys.size||drumHolds.size){notify('Release keys and pads first.');return;}const copy=structuredClone(p);copy.id=uid();copy.name+=' copy';patterns().push(copy);id=copy.id;changed();render()};q('#prDeletePattern').onclick=()=>{if(keys.size||drumHolds.size){notify('Release keys and pads first.');return;}if(!confirmDelete())return;};function confirmDelete(){if(p.notes.length&&!q('#prDeletePattern').dataset.confirm){q('#prDeletePattern').dataset.confirm='yes';q('#prDeletePattern').textContent='CONFIRM DELETE (linked clips removed)';return false;}patterns().splice(patterns().indexOf(p),1);id=null;changed({removedPattern:p.id});render();return true;}
 q('#prAdd').onclick=()=>addToPlaylist(p.id);q('#prInstrument').onchange=e=>act(p=>{p.instrument=e.target.value;p.voice={}});q('#prBeats').onchange=e=>act(p=>{const n=+e.target.value;if(p.notes.some(x=>x.start+x.length>n))throw Error('Move or trim notes before shortening the pattern.');p.beats=n});q('#prOctave').onchange=e=>{octave=+e.target.value;render()};q('#prSnap').onchange=e=>snap=+e.target.value;q('#prLength').onchange=e=>length=Math.max(.125,Math.min(32,+e.target.value||1));q('#prVelocity').oninput=e=>velocity=+e.target.value;q('#prZoom').onchange=e=>{zoom=+e.target.value;render()};q('#prRowZoom').onchange=e=>{rowHeight=+e.target.value;render()};q('#prTool').onchange=e=>{mode=e.target.value;render()};q('#prMulti').onchange=e=>multi=e.target.checked;
 all('[data-pr-voice]').forEach(el=>el.onchange=()=>act(p=>p.voice[el.dataset.prVoice]=+el.value));
 for(const [control,field]of [['prPitchEdit','pitch'],['prStartEdit','start'],['prLengthEdit','length'],['prVelocityEdit','velocity']])if(first)q('#'+control).onchange=e=>{const v=+e.target.value;if(first[field]===v)return;act(p=>{if(!Number.isFinite(v))throw Error('Enter a number.');first[field]=v;if(first.pitch<24||first.pitch>108||!Number.isInteger(first.pitch)||first.length<.03125||first.length>32||first.start<0||first.start+first.length>p.beats||first.velocity<.01||first.velocity>1)throw Error('Keep the note inside the pattern and allowed range.');});};
 q('#prDelete').onclick=()=>act(p=>p.notes=p.notes.filter(n=>!selected.has(n.id)));q('#prCopy').onclick=()=>{clipboard=structuredClone(p.notes.filter(n=>selected.has(n.id)));render()};q('#prPaste').onclick=()=>{const at=+q('#prPasteAt').value;act(p=>{const start=Math.min(...clipboard.map(n=>n.start));insert(p,clipboard.map(n=>({...n,id:uid(),start:n.start-start+at})))})};q('#prDuplicate').onclick=()=>act(p=>{const rows=p.notes.filter(n=>selected.has(n.id)),start=Math.min(...rows.map(n=>n.start)),end=Math.max(...rows.map(n=>n.start+n.length));insert(p,rows.map(n=>({...n,id:uid(),start:n.start+end-start})))});q('#prQuantize').onclick=()=>act(p=>{for(const n of p.notes)if(!selected.size||selected.has(n.id)){n.start=Math.max(0,Math.min(p.beats-n.length,quantize(n.start)));n.length=Math.max(.03125,Math.min(32,p.beats-n.start,Math.max(snap,quantize(n.length))));}});
 for(const [control,from,to]of [['prUndo',undo,redo],['prRedo',redo,undo]])q('#'+control).onclick=()=>{if(!from.length)return;to.push(structuredClone(p));Object.assign(p,from.pop());changed();render()};
 const choose=id=>{if(!multi)selected.clear();selected.has(id)?selected.delete(id):selected.add(id);render()};all('[data-pr-select]').forEach(el=>el.onclick=()=>choose(el.parentElement.dataset.prNote));
 const grid=q('#prGrid');grid.style.touchAction=mode==='pan'?'pan-x pan-y':'none';grid.onpointerdown=e=>{if(e.button>0||drag||mode==='pan')return;const target=e.target.closest('[data-pr-note]'),n=target?p.notes.find(n=>n.id===target.dataset.prNote):null,r=grid.getBoundingClientRect(),start=Math.max(0,Math.min(p.beats-length,quantize((e.clientX-r.left)/zoom))),pitch=Math.max(base,Math.min(top,top-Math.floor((e.clientY-r.top)/rowHeight)));if(n&&mode==='erase'){act(p=>p.notes=p.notes.filter(x=>x!==n));return;}if(!n&&mode==='select'){selected.clear();render();return;}grid.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,n:n?{...n}:null,target:n?.id,start,pitch,resize:!!e.target.closest('[data-pr-resize]'),dx:0,dy:0};e.preventDefault();};grid.onpointermove=e=>{if(drag?.id!==e.pointerId)return;drag.dx=e.clientX-drag.x;drag.dy=e.clientY-drag.y;const el=all('[data-pr-note]');for(const n of el)if(n.dataset.prNote===drag.target){if(drag.resize)n.style.width=Math.max(36,(drag.n.length+quantize(drag.dx/zoom))*zoom)+'px';else n.style.transform=`translate(${quantize(drag.dx/zoom)*zoom}px,${Math.round(drag.dy/rowHeight)*rowHeight}px)`;}};const release=(e,cancel)=>{if(drag?.id!==e.pointerId)return;const d=drag;drag=null;try{grid.releasePointerCapture(e.pointerId)}catch{}if(cancel){render();return;}if(d.n&&Math.hypot(d.dx,d.dy)<5&&!d.resize){choose(d.target);return;}act(p=>{if(!d.n)insert(p,[{id:uid(),pitch:d.pitch,start:d.start,length:Math.min(length,p.beats-d.start),velocity}]);else{const n=p.notes.find(n=>n.id===d.target);if(d.resize)n.length=Math.max(.125,Math.min(32,p.beats-n.start,d.n.length+quantize(d.dx/zoom)));else{n.start=Math.max(0,Math.min(p.beats-n.length,d.n.start+quantize(d.dx/zoom)));n.pitch=Math.max(24,Math.min(108,d.n.pitch-Math.round(d.dy/rowHeight)));}selected=new Set([n.id]);}});};grid.onpointerup=e=>release(e,false);grid.onpointercancel=e=>release(e,true);
 q('#prRecord').onclick=()=>{if(!armed&&(keys.size||drumHolds.size)){notify('Release keys and pads before starting note capture.');return;}if(armed)for(const key of [...keys.values()])key.finish?.();armed=!armed;recordAt=null;render()};all('[data-pr-key]').forEach(el=>{let lastPointer=-Infinity;const down=id=>{if(keys.has(id))return;const pitch=+el.dataset.prKey,started=clock();const beat=musicalClock();if(armed&&recordAt===null)recordAt=beat;keys.set(id,{voice:hit(p,pitch,velocity),pitch,started,beat,pattern:p,element:el,pointerId:id,at:recordAt,finish:()=>up(id,false),timer:setTimeout(()=>up(id,false),8000)});el.classList.add('held');};const up=(id,cancel)=>{const key=keys.get(id);if(!key)return;keys.delete(id);try{if(typeof id==='number')el.releasePointerCapture(id)}catch{}clearTimeout(key.timer);key.voice?.stop();el.classList.remove('held');if(armed&&!cancel){const start=Math.max(0,key.beat-key.at),len=Math.max(.03125,Math.min(32,musicalClock()-key.beat));act(p=>{if(start+len>128)throw Error('Stop capture before 32 bars.');p.beats=Math.max(p.beats,Math.ceil((start+len)/4)*4);insert(p,[{id:uid(),pitch:key.pitch,start,length:len,velocity}])});}else if(!keys.size)render();};el.onpointerdown=e=>{lastPointer=clock();e.preventDefault();el.setPointerCapture(e.pointerId);down(e.pointerId)};el.onpointerup=e=>{lastPointer=clock();up(e.pointerId,false)};el.onpointercancel=e=>{lastPointer=clock();up(e.pointerId,true)};el.onlostpointercapture=e=>{lastPointer=clock();up(e.pointerId,true)};el.onclick=e=>{if(e.detail===0&&clock()-lastPointer>.35){const id='click-'+el.dataset.prKey;down(id);setTimeout(()=>up(id,false),180);}};});all('[data-pr-pad]').forEach(el=>{let lastPointer=-Infinity;el.onpointerdown=e=>{lastPointer=clock();e.preventDefault();el.setPointerCapture(e.pointerId);drumHolds.set(e.pointerId,{...padHit(+el.dataset.prPad),element:el});};el.onpointerup=el.onpointercancel=el.onlostpointercapture=e=>{lastPointer=clock();drumHolds.get(e.pointerId)?.stop?.();drumHolds.delete(e.pointerId);if(!keys.size&&!drumHolds.size)render();};el.onclick=e=>{if(e.detail===0&&clock()-lastPointer>.35){const voice=padHit(+el.dataset.prPad);setTimeout(()=>voice?.stop?.(),180)}};});
 if(scroll){q('.pr-scroll').scrollLeft=scroll.x;q('.pr-scroll').scrollTop=scroll.y;}if(focus)q('#'+focus)?.focus({preventScroll:true});rendering=false;
 }
 return{render,current:ensure,select(value){id=value;selected.clear();undo=[];redo=[];},position(beat){const head=q('.pr-playhead');if(head)head.style.left=beat*zoom+'px';},cancel(){drag=null;const held=[...keys.values()],capture=armed;keys.clear();armed=false;recordAt=null;for(const key of held){clearTimeout(key.timer);try{if(typeof key.pointerId==='number')key.element.releasePointerCapture(key.pointerId)}catch{}key.voice?.stop();}for(const [id,voice]of drumHolds){try{voice.element.releasePointerCapture(id)}catch{}voice.stop?.();}drumHolds.clear();if(capture&&held.length){remember();for(const key of held){const p=current(),start=Math.max(0,key.beat-key.at),length=Math.max(.03125,Math.min(32,musicalClock()-key.beat));if(key.pattern===p&&p.notes.length<256&&start+length<=128){p.beats=Math.max(p.beats,Math.ceil((start+length)/4)*4);p.notes.push({id:uid(),pitch:key.pitch,start,length,velocity});}}changed();}if(!root.hidden)render();},dispose(){this.cancel();root.replaceChildren();}};
}
